def _headers(token: str) -> dict:
    return {"Authorization": f"Bearer {token}", "Accept": "application/json"}


# Perch sometimes takes >30 s to answer one page, or returns 502 mid-pagination.
# Retry that one request instead of failing (and restarting) the whole pull.
_HTTP_ATTEMPTS = 4
_HTTP_TIMEOUT  = (10, 60)          # (connect, read) seconds
_HTTP_BACKOFF  = (5, 15, 45)       # sleep before attempts 2, 3, 4


def _perch_request(method: str, url: str, **kwargs) -> requests.Response:
    """requests.request with per-call retries on timeouts, connection errors, 429 and 5xx."""
    for attempt in range(1, _HTTP_ATTEMPTS + 1):
        try:
            resp = requests.request(method, url, timeout=_HTTP_TIMEOUT, **kwargs)
            if resp.status_code != 429 and resp.status_code < 500:
                resp.raise_for_status()
                return resp
            err: Exception = requests.exceptions.HTTPError(
                f"{resp.status_code} from {url}", response=resp)
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError) as e:
            err = e
        if attempt == _HTTP_ATTEMPTS:
            raise err
        wait = _HTTP_BACKOFF[attempt - 1]
        print(f"  Perch request failed ({type(err).__name__}); retry {attempt + 1}/"
              f"{_HTTP_ATTEMPTS} in {wait}s", file=sys.stderr)
        time.sleep(wait)

